"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2707],{11219:e=>{e.exports=JSON.parse('{"functions":[{"name":"GetCharacter","desc":"The seam. Defaults to `PlayerList:GetCharacterFromPlayer`.\\n\\nReplace it to test anything that needs a character without standing up the\\nCustomCharacter system:\\n\\n```lua\\nCharacterUtil.GetCharacter = function(player)\\n\\treturn fake_characters[player]\\nend\\n```","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"Model?\\n"}],"function_type":"static","source":{"line":82,"path":"src2/shared/EmberSharedLibrary/GameShared/Player/CharacterUtil.luau"}},{"name":"RootPart","desc":"The character\'s root part, or nil.\\n\\nRead fresh every time on purpose. The old session record cached a\\n`PrimaryPart` on `client`, which went stale across a respawn -- and with\\nCustomCharacter a character can be replaced without the player rejoining, so\\ncaching is wrong more often here than it would be in an ordinary place.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"BasePart?\\n"}],"function_type":"method","source":{"line":123,"path":"src2/shared/EmberSharedLibrary/GameShared/Player/CharacterUtil.luau"}},{"name":"Position","desc":"The character\'s world position, or nil.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"Vector3?\\n"}],"function_type":"method","source":{"line":132,"path":"src2/shared/EmberSharedLibrary/GameShared/Player/CharacterUtil.luau"}},{"name":"IsSpawned","desc":"Whether the player currently has a character in the world.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":142,"path":"src2/shared/EmberSharedLibrary/GameShared/Player/CharacterUtil.luau"}}],"properties":[],"types":[],"name":"CharacterUtil","desc":"How to get a player\'s character in this game.\\n\\n**`Player.Character` IS NOT VALID HERE.** The game runs the vendored\\nCustomCharacter system, which owns character lifetime itself; the Roblox\\nproperty is not the authority and may be nil or stale for a live player.\\n`PlayerList` is, and its own comment says why:\\n\\n> Futureproof way to get a character from a player. Maybe the Character\\n> property on the Player will be removed one day!\\n\\nEverywhere in `src/` that needs a character already goes through\\n`PlayerList:GetCharacterFromPlayer` -- the door actions, the landmine,\\nInteractionService2. src2 does too, through here.\\n\\nWHY A MODULE RATHER THAN THE CALL\\n\\nTwo reasons, both about not dragging a frozen system into places it does not\\nbelong.\\n\\n`PlayerList` is stateful: it tracks players, runs a server runner, and\\nregisters itself in `_G`. A module that requires it at load pulls all of that\\ninto anything that requires the module -- including a headless test place with\\nno players, where every lookup would return nil and every range check would\\nsilently fail closed.\\n\\nSo the require is LAZY and the lookup is one injectable seam. Production gets\\nthe real PlayerList without anyone wiring anything; a test overrides\\n`GetCharacter` and never triggers the require at all.","source":{"line":35,"path":"src2/shared/EmberSharedLibrary/GameShared/Player/CharacterUtil.luau"}}')}}]);